 taxa[id]={'latin':latin,'name':name or latin,'common_names':[name] if name else [],'synonyms':syn,'toxicity':tox,'traits':None,'check_before_picking':chars,'habitat':habitat,'season_text':season,'season_months':months,'stages':[],'caution':caution,'sources':src,'missing_data':missing,'review_status':'proposta documentata; revisione micologica/editoriale e foto da completare'}
 if tox.startswith('commestibile'):edible.append({'id':id,'name':name or latin,'latin':latin,'common_names':[name] if name else [],'synonyms':syn,'toxicity':tox,'months':months,'season':season,'habitat':habitat,'caution':caution,'sources':src})
